cd /tmp/dev && python3 - <<'EOF'
import sys, json, random
sys.path.insert(0,'/tmp/dev'); sys.path.insert(0,'/workspace/deps'); sys.path.insert(0,'/workspace/submission')
import t6
from common import validate
from harness import run
for trial in (2,4,15):
    rng = random.Random(trial*977+13)
    job = t6.random_campaign(rng)
    try:
        validate(job); print(trial, 'valid')
    except Exception as e:
        print(trial, 'invalid', e)
    out, err = run(job)
    print('  err:', err[:200])
    # detailed checks
    from common import integer, ident, prefix, address, fields, forest
    for k in ('version','seed'):
        pass
    try:
        rq, rp = forest(job['request_quotas'])
        oq, op = forest(job['offer_quotas'])
    except Exception as e:
        print('  forest', e)
        print('  rq', job['request_quotas'])
        print('  oq', job['offer_quotas'])
    for l in job['leases']:
        try: prefix(l['prefix'], (56,64))
        except Exception as e: print('  lease prefix', l['id'], l['prefix'], e)
    for o in job['offers']:
        try: prefix(o['prefix'])
        except Exception as e: print('  offer prefix', o['id'], o['prefix'], e)
        try: address(o['prefix'])
        except Exception: pass
    for r in job['requests']:
        try: address(r['target'])
        except Exception as e: print('  req target', r['id'], r['target'], e)
    print('  leases', [l['prefix'] for l in job['leases']])
